import{_ as n,a0 as s,w as p,s as u,ao as o,I as r,x as l,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"開源社區透明度的五個層次 | LCTT x X-CMD","titleTemplate":false,"description":"開源社區透明度的五個層次 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開源社區透明度的五個層次 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開源社區透明度的五個層次 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220212 5 levels of transparency for open source communities","title":"開源社區透明度的五個層次","tag":"202205","desc":""},"relativePath":"202205/20220212 5 levels of transparency for open source communities.md","filePath":"[post].md"}'),d={name:"202205/20220212 5 levels of transparency for open source communities.md"};function m(f,e,h,T,b,x){const t=s("Link");return p(),u("div",null,[e[20]||(e[20]=o('<h1 id="開源社區透明度的五個層次" tabindex="-1">開源社區透明度的五個層次 <a class="header-anchor" href="#開源社區透明度的五個層次" aria-label="Permalink to “開源社區透明度的五個層次”">​</a></h1><blockquote><p>如果想讓開源社區繁榮發展，管理者需要達到透明度的五個層次。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202205/15/150842yrvm9v5qbbd7a355.jpg" alt=""></p><p>開源社區的管理者必須意識到社區有五個層次的透明度，這對於建設繁榮發展的開源社區來説至關重要。</p><p>本文將詳細介紹各個層次及其目標與作用。不過首先，我想談一談透明度對開源社區的重要性。</p><h3 id="為什麼開源社區需要保證透明度" tabindex="-1">為什麼開源社區需要保證透明度？ <a class="header-anchor" href="#為什麼開源社區需要保證透明度" aria-label="Permalink to “為什麼開源社區需要保證透明度？”">​</a></h3><ul><li>透明能夠增進社區成員之間的信任，促進合作。</li><li>開放是社區合作和交流的前提。</li><li>只有在開放透明的環境下，開源工作才能避免矛盾與衝突。</li><li>社區管理者需要向參與者報告社區情況。</li><li>向成員公開社區各項情況，營造信任氛圍，有利於社區健康發展。</li></ul><h3 id="透明度的五個層次" tabindex="-1">透明度的五個層次 <a class="header-anchor" href="#透明度的五個層次" aria-label="Permalink to “透明度的五個層次”">​</a></h3><h4 id="層次一-發佈源碼" tabindex="-1">層次一：發佈源碼 <a class="header-anchor" href="#層次一-發佈源碼" aria-label="Permalink to “層次一：發佈源碼”">​</a></h4>',9)),r("p",null,[e[2]||(e[2]=l("在這一層次，社區需要遵循 ",-1)),a(t,{href:"https://opensource.org/licenses"},{default:i(()=>[...e[0]||(e[0]=[l("OSI 認可的許可證",-1)])]),_:1}),e[3]||(e[3]=l("，在 ",-1)),a(t,{href:"https://opensource.com/tags/git"},{default:i(()=>[...e[1]||(e[1]=[l("Git",-1)])]),_:1}),e[4]||(e[4]=l(" 等公開的版本控制系統上發佈源碼。",-1))]),e[21]||(e[21]=o('<p>層次一的目標在於創建開源項目。</p><ul><li>建立開源社區，理應達到這一層次。因為沒有公開源代碼，也就無所謂開源項目。</li><li>開源項目的核心便是參與者們編寫的源碼，並在 OSI 批准的許可證下授權。</li><li>公開的版本控制系統能夠促進合作，使得每一位開發者都能瞭解項目情況，理解合作模式。</li></ul><h4 id="層次二-發佈社區指南" tabindex="-1">層次二：發佈社區指南 <a class="header-anchor" href="#層次二-發佈社區指南" aria-label="Permalink to “層次二：發佈社區指南”">​</a></h4><p>達到這一層次，需要發佈相關文檔以及資源。也可通過組織活動來指導社區成員。</p><p>層次二的目標在於為一個開源項目建立和發展一個開源社區。</p><ul><li>建立一個活躍的社區需要的不僅僅是源代碼。</li><li>公開項目開展方式和貢獻方式，能夠吸引更多的開發者參與到項目當中。</li><li>為了推動社區的發展，管理者可能需要舉辦一些重要活動，併為貢獻者們籌辦一些特殊的活動。</li></ul><h4 id="層次三-繼往開來" tabindex="-1">層次三：繼往開來 <a class="header-anchor" href="#層次三-繼往開來" aria-label="Permalink to “層次三：繼往開來”">​</a></h4><p>到了這個層次，管理者有必要分享自己對於社區的見解，發佈項目進展情況報告。</p><p>層次三的目標在於繼往開來，確保社區進入後續階段後能夠更上一層樓，實現長遠發展。</p><ul><li>隨着開源社區的發展，社區內的情況將會越來越難以把握。</li><li>公開社區活動，讓成員意識到自己的付出能夠為公眾所見，為公眾所識。</li><li>在這一層次，無論是報告還是分析，發佈的時間並不固定，使用的工具也無定法。</li></ul><h4 id="層次四-掌握社區的動態" tabindex="-1">層次四：掌握社區的動態 <a class="header-anchor" href="#層次四-掌握社區的動態" aria-label="Permalink to “層次四：掌握社區的動態”">​</a></h4><p>這一層次就在於傾聽社區聲音：通過觀察社區活動，關注項目發展；跟進軟件開發進度，據此採取合適的應對措施。</p><p>層次四的目標在於保持科學嚴謹的態度，持續把握社區的發展情況及發展軌跡，引導社區朝着下一個層次邁進。</p><ul><li>建立報告機制，運用分析工具，掌握社區動態。</li><li>將社區的各項活動與社區成員的反響與基線和社區內的其他活動進行比較。</li><li>堅持傾聽社區聲音，形成對於社區更深刻的見解。</li></ul><h4 id="層次五-維護社區-長久發展" tabindex="-1">層次五：維護社區，長久發展 <a class="header-anchor" href="#層次五-維護社區-長久發展" aria-label="Permalink to “層次五：維護社區，長久發展”">​</a></h4><p>最後一個層次就是依據社區各項指標，提高社區成員的參與度。</p><p>層次五的目標在於制定行之有效、能夠產生積極影響的決策方案，讓開發者更好地參與社區項目。</p><ul><li>適當調整系統，以適應社區各項指標的變動。</li><li>跟進這些變動，理解它們是如何通過各項指標和數據分析體現出來的。</li><li>針對社區維護者與開發者，制定服務等級協議和問責制度，為其設立參與度目標，確保項目整體順利進行。</li></ul><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>開源社區管理者需要做到上述五個層次，保證透明度，才能構建起一個繁榮發展的社區。</p><hr>',21)),r("p",null,[e[6]||(e[6]=l("via: ",-1)),a(t,{href:"https://opensource.com/article/22/2/transparency-open-source-communities"},{default:i(()=>[...e[5]||(e[5]=[l("https://opensource.com/article/22/2/transparency-open-source-communities",-1)])]),_:1})]),r("p",null,[e[11]||(e[11]=l("作者：",-1)),a(t,{href:"https://opensource.com/users/egaleano"},{default:i(()=>[...e[7]||(e[7]=[l("Emilio Galeano Gryciuk",-1)])]),_:1}),e[12]||(e[12]=l(" 選題：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[8]||(e[8]=[l("lujun9972",-1)])]),_:1}),e[13]||(e[13]=l(" 譯者：",-1)),a(t,{href:"https://github.com/aREversez"},{default:i(()=>[...e[9]||(e[9]=[l("aREversez",-1)])]),_:1}),e[14]||(e[14]=l(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[10]||(e[10]=[l("wxy",-1)])]),_:1})]),r("p",null,[e[17]||(e[17]=l("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[15]||(e[15]=[l("LCTT",-1)])]),_:1}),e[18]||(e[18]=l(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:i(()=>[...e[16]||(e[16]=[l("Linux中國",-1)])]),_:1}),e[19]||(e[19]=l(" 榮譽推出",-1))])])}const P=n(d,[["render",m]]);export{k as __pageData,P as default};
